const icon = (name, extra='') => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}>${icons[name] || icons.explore}</svg>`;
const themeNames = {all:'모든 풍경',lake:'호수',coast:'바다',forest:'숲길',city:'도시'};
const regions = {춘천:'춘천, 강원',강릉:'강릉, 강원',서울:'서울',제주:'제주'};
const prefs = loadPreferences();
const state = {
  view:['explore','journey','drive','memories','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'explore',
  selected:routes.find(r=>r.id===prefs.selectedId)||routes[0],
  filters:{region:['춘천','강릉','서울','제주'].includes(prefs.region)?prefs.region:'all',theme:['lake','coast','forest','city'].includes(prefs.theme)?prefs.theme:'all',maxMinutes:Number.isInteger(prefs.maxMinutes)&&prefs.maxMinutes>=1&&prefs.maxMinutes<=720?prefs.maxMinutes:90,query:''},
  bookmarks:Array.isArray(prefs.bookmarks)?prefs.bookmarks.filter(id=>routes.some(r=>r.id===id)):[],
  sort:'match',allResults:false,moving:false,simulation:false,progress:0,scene:'lake',gpsWatch:null,gps:null,gpsStatus:'',
  mapMode:'online',roadRoute:null,roadLoading:false,places:[],placesLoaded:false,placesLoading:false,clips:[],clipsLoading:false,clipsError:'',cameraActive:false,cameraPending:false,
  autoSound:prefs.autoSound!==false,includeLocation:prefs.includeLocation===true,volume:typeof prefs.volume==='number'?Math.min(.8,Math.max(0,prefs.volume)):.35,providerStatus:{},aiLoading:false,aiResult:null,aiError:'',
};
// Stored selection and filters can come from different previous screens.
const initialCandidates=rankRoutes(routes,state.filters);
if(initialCandidates.length&&!initialCandidates.some(route=>route.id===state.selected.id)){
  state.selected=routes.find(route=>route.id===initialCandidates[0].id);
}
state.scene=state.selected.theme;
const audioEngine=createAudioEngine();
const camera=createCameraRecorder();
audioEngine.setVolume(state.volume);
audioEngine.setScene(state.scene);
let map=null, mapMarker=null, simTimer=null, toastTimer=null, clipUrls=[], dialogUrl=null, weatherToken=0, recordingStarted=0,cameraStream=null,gpsToken=0,roadToken=0,placesToken=0,aiToken=0;
const main=$('#main-content');
const MAX_BYTES=100*1024*1024;

function persist(){
  const ok=savePreferences({selectedId:state.selected.id,region:state.filters.region,theme:state.filters.theme,maxMinutes:state.filters.maxMinutes,bookmarks:state.bookmarks,autoSound:state.autoSound,includeLocation:state.includeLocation,volume:state.volume});
  if(!ok)toast('이 브라우저에서 설정을 보존할 수 없습니다. 현재 세션에는 적용됩니다.',true);
}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-region').innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;toastTimer=setTimeout(()=>$('#toast-region').innerHTML='',4500);}
function allowed(action){if(canInteract({moving:state.moving},action))return true;toast('운전 모드에서는 사용할 수 없습니다. 정차 모드로 전환해 주세요.');return false;}
function updateClock(){const now=new Date();$('#clock').textContent=now.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false});$('#clock').dateTime=now.toISOString();}
function updateHeader(){
  $('#location-label').textContent=regions[state.selected.region]||state.selected.region;
  $('#mode-label').textContent=state.moving?'운전 모드 · 시연':'정차 모드';
  $('#drive-mode-toggle').classList.toggle('moving',state.moving);
  $('#drive-mode-toggle').setAttribute('aria-pressed',String(state.moving));
  $('#main-nav').innerHTML=[['explore','explore','탐색'],['journey','route','나의 코스'],['drive','drive','드라이브'],['memories','film','여정 기록'],['settings','settings','설정']].map(([v,i,l])=>`<a href="#${v}" class="nav-item ${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('');
}
async function updateWeather(){
  const token=++weatherToken;
  $('#weather-label').textContent='날씨 확인 중';
  const [lat,lon]=state.selected.coordinates[0];
  try{const data=await getWeather(lat,lon);if(token!==weatherToken)return;const label=data.weatherCode<=1?'맑음':data.weatherCode<=3?'구름':data.weatherCode<=48?'안개':data.weatherCode>=71&&data.weatherCode<=77?'눈':'비';$('#weather-label').textContent=`${Math.round(data.temperature)}° · ${label}`;$('#weather-label').title=`${data.source} · ${data.observedAt} · 코스 출발지 날씨`;}catch{if(token===weatherToken){$('#weather-label').textContent='날씨 연결 대기';$('#weather-label').title='온라인 날씨 API를 이용할 수 없습니다.';}}
}
function intro(kicker,title,description,extra=''){return `<div class="page-intro"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function safetyBanner(){return state.moving?`<div class="safety-banner">${icon('shield')}<span>운전 모드 시연 중 · 탐색과 영상은 정차 후 이용할 수 있어요.</span><button class="text-button" data-action="park">정차하기 ${icon('arrow')}</button></div>`:'';}
function restricted(title){return `${safetyBanner()}<section class="panel restricted-card"><div class="icon">${icon('lock')}</div><h2>${title}</h2><p>지금은 운전에 집중할 시간이에요.<br>정차 모드로 전환하면 코스를 살펴보고 기록을 관리할 수 있습니다.</p><button class="primary-button" data-action="park">정차 모드로 전환 ${icon('arrow')}</button></section>`;}
function filterBar(){return `<div class="filter-bar"><span class="filter-label">${icon('sliders')} 나의 취향</span><label class="sr-only" for="region-filter">출발 권역</label><select id="region-filter" aria-label="출발 권역"><option value="all">모든 지역</option>${Object.keys(regions).map(v=>`<option value="${v}" ${state.filters.region===v?'selected':''}>${v} 출발</option>`).join('')}</select><span class="filter-sep"></span><label class="time-budget" for="time-filter"><span>여유 시간</span><input id="time-filter" type="number" inputmode="numeric" min="1" max="720" step="1" list="time-presets" value="${state.filters.maxMinutes}" aria-label="드라이브 시간 예산, 1분부터 720분까지 직접 입력" required><span>분</span></label><datalist id="time-presets">${[45,60,90,120,180].map(v=>`<option value="${v}">${v}분</option>`).join('')}</datalist><div class="filter-theme" aria-label="선호 풍경">${Object.entries(themeNames).map(([v,n])=>`<button type="button" class="theme-chip ${state.filters.theme===v?'active':''}" data-action="theme" data-value="${v}" aria-pressed="${state.filters.theme===v}">${n}</button>`).join('')}</div></div>`;}
function invalidateAI(){aiToken++;state.aiLoading=false;state.aiResult=null;state.aiError='';}
function getRanked(){const ranked=rankRoutes(routes,state.filters);if(state.sort==='duration')ranked.sort((a,b)=>a.durationMin-b.durationMin);if(state.sort==='distance')ranked.sort((a,b)=>a.distanceKm-b.distanceKm);if(state.sort==='saved')return ranked.filter(r=>state.bookmarks.includes(r.id));return ranked;}
function stats(route){return `<div class="route-stats"><span>${icon('clock')} ${route.durationMin}분</span><span>${icon('route')} ${route.distanceKm} km</span><span class="scenery-stat">${icon('leaf')} ${themeNames[route.theme]} 중심</span></div>`;}
function bookmarkButton(route,extra=''){const saved=state.bookmarks.includes(route.id);return `<button class="icon-button ${saved?'saved':''} ${extra}" data-action="bookmark" data-id="${esc(route.id)}" aria-label="${esc(route.title)} ${saved?'저장 해제':'저장'}" aria-pressed="${saved}">${icon('heart',saved?'fill="currentColor"':'')}</button>`;}
function routeCard(route){return `<article class="route-card ${state.selected.id===route.id?'selected':''}"><div class="route-card-heading"><span class="scene-tag">${icon(route.theme)} ${esc(route.region)} · ${themeNames[route.theme]}</span>${bookmarkButton(route)}</div><button class="card-select" data-action="select-route" data-id="${route.id}" aria-label="${esc(route.title)} 코스 보기"><span class="route-card-number">${String(routes.findIndex(item=>item.id===route.id)+1).padStart(2,'0')}</span><h3>${esc(route.title)}</h3><p>${esc(route.tags.slice(0,3).join(' · '))}</p><span class="card-link">코스 살펴보기 ${icon('arrow')}</span></button><div class="card-stats"><span>${icon('clock')}${route.durationMin}분</span><span>${icon('route')}${route.distanceKm}km</span></div></article>`;}

function soundCard(compact=false){const a=audioEngine.getState(),soundScene=a.source==='ambient'&&a.playing?a.scene:state.scene,sound=selectSound(soundScene);return `<section class="panel sound-card ${compact?'audio-compact':''}" aria-label="풍경 사운드 플레이어"><div class="sound-header"><h2>풍경을 닮은 사운드</h2></div><h3 class="sound-title">${esc(a.source==='file'?a.fileName:sound.title)}</h3><p class="sound-artist">${a.source==='file'?'내가 가져온 음악':'합성 앰비언트 사운드'}</p><p class="sound-context">${icon(soundScene)} ${a.source==='file'?'개인 음원 재생':`${themeNames[soundScene]} 구간 · ${sound.mood}`}</p><div class="player-controls"><button data-action="sound-prev" aria-label="이전 풍경 사운드">${icon('prev')}</button><button class="play-button" data-action="sound-play" aria-label="${a.playing?'사운드 일시정지':'사운드 재생'}">${icon(a.playing?'pause':'play')}</button><button data-action="sound-next" aria-label="다음 풍경 사운드">${icon('next')}</button></div><label class="volume-row" aria-label="음량">${icon('volume')}<input id="volume-control" type="range" min="0" max="80" value="${Math.round(state.volume*100)}" aria-label="음량 조절"></label><p class="sound-source">${a.source==='file'?'이 기기의 파일 · 외부 전송 없음':'합성 사운드'}</p>${!state.moving?`<button class="sound-upload" data-action="upload-audio">${icon('upload')} 음악 파일 가져오기</button>`:''}${a.source==='file'&&!state.moving?'<button class="text-button" data-action="original-audio" style="justify-self:center;margin-top:10px">합성 사운드로 전환</button>':''}</section>`;}
function journeyMini(){const r=state.selected;return `<section class="panel mini-journey"><div class="section-heading"><h2>경유지</h2><span class="journey-count">${r.stops.length}곳</span></div><ol class="stop-list">${r.stops.map((s,i)=>`<li class="stop-row"><span class="stop-marker"></span><div><h3 class="stop-name">${esc(s.name)}</h3><p class="stop-desc">${i===0?'':themeNames[s.scene]}</p></div><span class="stop-time">${i===0?'출발':i===r.stops.length-1?'도착':String(i).padStart(2,'0')}</span></li>`).join('')}</ol><div class="journey-bottom"><span>코스 상세</span><button class="text-button" data-action="view" data-value="journey" aria-label="나의 코스 자세히 보기">${icon('arrow')}</button></div></section>`;}
function aiPanel(){const result=state.aiResult;return `<section class="ai-panel" aria-label="선택형 AI 코스 추천"><div class="ai-panel-heading"><div><span class="mini-kicker">AI 추천</span><h3>조건에 맞는 코스 비교</h3></div><button type="button" class="secondary-button" data-action="ai-recommend" ${state.aiLoading||!getRanked().length?'disabled':''}>${icon('explore')} ${state.aiLoading?'AI 추천을 기다리는 중…':'AI로 코스 추천'}</button></div><p class="ai-disclosure">추천 조건과 후보 코스를 OpenAI로 전송합니다.</p><details class="connection-details"><summary>연결 안내</summary><p>서버의 OpenAI API 키가 필요합니다. 연결 상태는 설정에서 확인할 수 있습니다.</p></details>${state.aiLoading?'<button type="button" class="text-button" data-action="ai-cancel">추천 결과 적용 취소</button>':''}${state.aiError?`<p class="inline-error">${esc(state.aiError)}</p>`:''}${result?`<div class="ai-result"><span class="source-pill">${esc(result.source)} · ${esc(result.model)} · 실제 API 응답</span>${result.recommendations.map((item,i)=>{const route=routes.find(r=>r.id===item.routeId);return `<article><div class="ai-result-title"><b>${String(i+1).padStart(2,'0')}. ${esc(route.title)}</b><button type="button" class="text-button" data-action="select-route" data-id="${route.id}">코스 보기 ${icon('arrow')}</button></div><p>${esc(item.reason)}</p></article>`;}).join('')}<small>AI 추천 이유는 검토가 필요할 수 있습니다. 시간·거리·도로 안전성은 기존 시연 데이터와 별개로 확인하세요.</small></div>`:''}</section>`;}
function renderExplore(){if(state.moving)return intro('코스 탐색','운전 모드가 켜져 있습니다.','정차 모드에서 코스를 변경할 수 있습니다.')+restricted('탐색은 정차 후에');const ranked=getRanked();const r=state.selected;const alternatives=ranked.filter(v=>v.id!==r.id).slice(0,3),shown=state.allResults?ranked:alternatives.length?alternatives:ranked.slice(0,3);return `${intro('FIND YOUR SCENE','코스 탐색','마음이 가는 풍경을 고르고, 나만의 드라이브를 준비하세요.')}<div class="dashboard-grid"><div class="main-column"><section><form id="recommendation-form">${filterBar()}${state.allResults?`<div class="search-row"><div class="search-field">${icon('search')}<input type="search" id="route-search" placeholder="지역, 코스, 풍경을 찾아보세요" value="${esc(state.filters.query)}" aria-label="코스 검색"></div><select id="sort-select" class="sort-select" aria-label="코스 정렬"><option value="match" ${state.sort==='match'?'selected':''}>취향 매치순</option><option value="duration" ${state.sort==='duration'?'selected':''}>짧은 시간순</option><option value="distance" ${state.sort==='distance'?'selected':''}>짧은 거리순</option><option value="saved" ${state.sort==='saved'?'selected':''}>저장한 코스</option></select><button class="primary-button" type="submit">코스 찾기 ${icon('arrow')}</button></div>`:''}</form>${ranked.length?`<article class="hero"><div class="hero-map">${mapPanel()}</div><div class="hero-copy"><div class="hero-top"><span class="eyebrow">추천 코스 · ${esc(r.region)}</span>${bookmarkButton(r)}</div><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><div class="hero-bottom">${stats(r)}<button class="primary-button" data-action="view" data-value="journey">코스 보기 ${icon('arrow')}</button></div></div></article>`:`<section class="empty-state"><div class="icon">${icon('explore')}</div><h2>이 조건에 맞는 길을 아직 찾지 못했어요.</h2><p>시간을 조금 늘리거나 다른 지역을 선택해 보세요. 추천 조건과 다른 코스를 표시하지 않습니다.</p><button class="secondary-button" data-action="reset-filters">모든 풍경 다시 보기 ${icon('arrow')}</button></section>`}</section><section><div class="section-heading"><h2>${state.allResults?'취향에 맞는 모든 코스':'다른 코스'}</h2><button class="text-button" data-action="all-routes">${state.allResults?'추천 화면으로':'모든 코스 보기'} ${icon('arrow')}</button></div>${shown.length?`<div class="route-grid ${state.allResults?'full-results':''}">${shown.map(routeCard).join('')}</div>`:`<div class="empty-state search-empty"><h2>조건에 맞는 코스가 없습니다.</h2><p>지금 조건에 맞는 ${state.sort==='saved'?'저장된 ':''}코스가 없어요. 지역이나 시간 예산을 바꾸면 다른 풍경을 만날 수 있습니다.</p><button class="secondary-button" data-action="reset-filters">전체 코스 둘러보기 ${icon('arrow')}</button></div>`}<p class="recommendation-note">${icon('info')} 시간·거리는 예시입니다.</p>${!state.allResults?'<button class="text-button" data-action="recommend" style="margin-top:10px">다시 추천 '+icon('refresh')+'</button>':''}<div id="ai-panel-slot">${aiPanel()}</div></section></div><aside class="side-column">${journeyMini()}${soundCard()}<p class="ambient-note">8개의 예시 코스로 드라이브를 체험하세요.<br>시간·거리와 풍경 포인트는 시연 데이터입니다.</p></aside></div>`;}
function renderJourney(){const r=state.selected,rank=rankRoutes([r],{...state.filters,region:'all',maxMinutes:Math.max(state.filters.maxMinutes,r.durationMin),query:''})[0];if(state.moving)return intro('코스 상세','운전 모드가 켜져 있습니다.','드라이브 화면에서 진행 상황을 확인하세요.')+restricted('코스 변경은 정차 후에');return `${intro('ROUTE DETAILS','코스 상세','경로, 시간, 경유지를 확인하고 시뮬레이션을 시작하세요.')}<div class="map-layout">${mapPanel()}<section class="panel route-detail"><span class="eyebrow">${esc(r.region)} / CURATED SCENIC ROUTE</span><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><h2>${esc(r.title)}</h2>${bookmarkButton(r)}</div><p>${esc(r.description)}</p><div class="detail-stats"><div><strong>${r.durationMin}<small> 분</small></strong><small>예상 시간 · 시연</small></div><div><strong>${r.distanceKm}<small> km</small></strong><small>코스 거리 · 예시</small></div><div><strong>${r.stops.length}</strong><small>풍경 포인트</small></div></div><h3 style="font-size:12px">이 코스를 추천하는 이유</h3><ul class="reason-list">${(rank?.reasons||['취향을 고려한 큐레이션 코스']).map(v=>`<li>${icon('check')}${esc(v)}</li>`).join('')}</ul><div class="detail-actions"><button class="primary-button" data-action="start-simulation">드라이브 시뮬레이션 ${icon('arrow')}</button><button class="secondary-button" data-action="view" data-value="drive" aria-label="주행 옵션 보기">${icon('settings')}</button></div><p class="route-note">지도 선은 풍경 포인트를 연결한 예시입니다. 실제 도로 안내와 교통 상황은 제공하지 않습니다.</p>${state.roadRoute?`<p class="analysis-result">${esc(state.roadRoute.source)} 도로 경로 · ${state.roadRoute.distanceKm} km / ${state.roadRoute.durationMin}분</p>`:`<button class="text-button" data-action="road-route" style="margin-top:12px" ${state.roadLoading?'disabled':''}>${state.roadLoading?'도로 경로 확인 중…':'도로 경로 불러오기'} ${icon('arrowUp')}</button>`}</section></div><section class="panel route-timeline"><div class="section-heading"><h2>길 위에서 만날 풍경</h2><span class="small-tag">경유지 예시</span></div><div class="horizontal-stops">${r.stops.map((s,i)=>`<article class="timeline-stop"><span>${String(i+1).padStart(2,'0')} / ${themeNames[s.scene]}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p></article>`).join('')}</div><p class="route-note">각 지점은 관심 지역을 뜻합니다. 실제 주차·진입 가능 여부와 도로 상태를 먼저 확인해 주세요.</p>${placesSection()}</section>`;}
function placesSection(){return `<div class="places-section"><div class="section-heading"><h3 style="font-size:12px">출발지 주변 관광정보</h3><button class="text-button" data-action="load-places" ${state.placesLoading?'disabled':''}>${state.placesLoading?'확인 중…':state.placesLoaded?'다시 조회':'관광정보 API로 조회'} ${icon('arrowUp')}</button></div><p class="route-note" style="margin-top:0">출발지 반경 10 km의 관광정보를 확인합니다.</p><details class="connection-details"><summary>관광정보 출처와 연결 안내</summary><p>한국관광공사 TourAPI · 서버 인증키 설정 시 실제 조회</p></details>${state.placesLoaded?state.places.length?`<div class="place-grid">${state.places.slice(0,6).map(p=>`<article class="place-card"><h4>${esc(p.title)}</h4><p>${esc(p.address)}</p><span>한국관광공사 TourAPI</span></article>`).join('')}</div>`:'<p class="route-note">현재 조회된 주변 관광정보가 없습니다.</p>':''}</div>`;}
function mapPanel(){return `<section class="map-panel" aria-label="${esc(state.selected.title)} 코스 지도"><div id="map-canvas" class="map-canvas"></div><div class="map-top-overlay"><span class="map-badge">${icon('pin')} ${esc(state.selected.region)} · ${state.roadRoute?'도로 경로':'경관 포인트'}</span><button class="map-toggle" data-action="toggle-map">${icon('map')} ${state.mapMode==='diagram'?'실제 지도 보기':'코스 도식 보기'}</button></div><div class="map-bottom">${state.gpsWatch!==null&&state.gps?`GPS 수신 · 오차 약 ${Math.round(state.gps.accuracy)}m`:state.roadRoute?'도로 경로 API 응답':'경유지 연결선 · 실제 도로 안내 아님'} <span>${state.selected.stops.length}개의 포인트</span></div></section>`;}

function renderDrive(){const r=state.selected,p=projectProgress(r,state.progress),stop=r.stops[p.stopIndex]||r.stops[0];return `${intro('DRIVE DEMO','드라이브','예시 코스의 진행 상황과 사운드를 확인하는 웹 시뮬레이션입니다.')} ${safetyBanner()}<div class="driving-view"><div>${mapPanel()}<div class="drive-guidance">${icon(state.scene)}<div><b>${esc(stop.name)}</b><span>${themeNames[state.scene]} 풍경 구간 · ${state.gpsWatch!==null?'위치 기반 추정':'샘플 경관 데이터'} · 실제 내비게이션 아님</span></div></div></div><aside class="side-column"><section class="panel drive-status"><span class="eyebrow">${state.simulation?'SIMULATION RUNNING':state.gpsWatch!==null?'BROWSER GPS':'시뮬레이션 대기'}</span><h2>${esc(r.title)}</h2><div class="drive-meta"><div><strong id="drive-remaining">${p.remainingMin}<small>분</small></strong><p>남은 시간 · 시연 값</p></div><div><strong id="drive-distance">${p.distanceKm.toFixed(1)}<small> / ${r.distanceKm} km</small></strong><p>진행 거리 · 예시</p></div></div><div class="progress-track"><span id="drive-progress-bar" style="width:${state.progress*100}%"></span></div><div class="progress-labels"><span>출발</span><span id="drive-progress-value">${Math.round(state.progress*100)}% 진행</span><span>도착</span></div><div class="scene-state"><span class="scene-state-icon">${icon(state.scene)}</span><div><h3>${themeNames[state.scene]} · ${selectSound(state.scene).title}</h3><p>${state.autoSound?'구간별 합성 사운드 자동 전환':'사운드 자동 전환 꺼짐'}</p></div></div><div class="drive-actions">${state.moving?`<button class="primary-button" data-action="park">${icon('pause')} 정차하기</button><button class="secondary-button" data-action="finish-drive">${icon('stop')} 시연 종료</button>`:`<button class="primary-button" data-action="start-simulation">${icon('play')} ${state.progress>0&&state.progress<1?'시뮬레이션 계속':'시뮬레이션 시작'}</button><button class="secondary-button" data-action="start-gps">${icon('gps')} GPS 시작</button>`}</div>${!state.moving?`<label class="drive-legend" for="drive-scrubber">시연 위치 이동 · 실제 이동과 무관</label><input id="drive-scrubber" class="drive-slider" type="range" min="0" max="100" value="${Math.round(state.progress*100)}" aria-label="시뮬레이션 진행 위치"><div class="demo-choice" aria-label="경관 사운드 체험">${['lake','coast','forest','city'].map(s=>`<button class="${state.scene===s?'active':''}" data-action="scene" data-value="${s}">${themeNames[s]} 체험</button>`).join('')}</div>`:''}<p class="drive-legend">${state.gpsStatus?esc(state.gpsStatus)+'<br>':''}시뮬레이션은 약 2분에 걸쳐 예시 코스를 재생합니다. GPS는 브라우저 위치 권한을 허용한 경우에만 사용하며, 차량 속도·안전 상태와 연결되지 않습니다.</p></section>${soundCard(true)}</aside></div>`;}
function renderMemories(){if(state.moving)return intro('RECORDINGS','영상 기록','이 기기에 저장한 영상을 관리합니다.')+restricted('영상은 정차한 뒤에');return `${intro('RECORDINGS','영상 기록','영상 가져오기, 카메라 녹화, 다운로드를 지원합니다.')}<section class="panel memory-toolbar"><div><h2>영상 추가</h2><p>영상 파일 가져오기 또는 브라우저 카메라 사용 · 최대 100 MB</p></div><div class="toolbar-actions"><button class="secondary-button" data-action="upload-video">${icon('upload')} 영상 가져오기</button><button class="primary-button" data-action="camera-start" ${state.cameraActive||state.cameraPending?'disabled':''}>${icon('camera')} ${state.cameraPending?'카메라 연결 중…':'카메라 동의 · 녹화'}</button></div></section>${state.cameraActive?`<section class="panel camera-panel"><div class="section-heading"><h2><span class="recording-dot"></span>브라우저 카메라 녹화 중</h2><button class="secondary-button" data-action="camera-stop">${icon('stop')} 녹화 종료 · 저장</button></div><video id="camera-preview" autoplay muted playsinline></video><p class="provenance-note">음성 없이 최대 2분 녹화합니다. 종료 후 현재 기기에 저장되며 차량 카메라와는 연결되어 있지 않습니다.</p></section>`:''}${state.clipsError?`<p class="inline-error">${esc(state.clipsError)} <button class="text-button" data-action="reload-clips">다시 시도</button></p>`:''}${state.clipsLoading?'<p class="loading-text">나의 기록을 불러오고 있어요…</p>':`<div class="section-heading"><h2>나의 기록 <span class="muted" style="font-size:12px;margin-left:6px">${state.clips.length}</span></h2><button class="text-button" data-action="export-all" ${state.clips.length?'':'disabled'}>메타데이터 내보내기 ${icon('download')}</button></div><div class="memory-grid">${state.clips.length?state.clips.map(clipCard).join(''):`<section class="empty-state"><div class="icon">${icon('film')}</div><h2>저장된 영상이 없습니다.</h2><p>드라이브에서 만난 영상을 가져와 보세요.<br>영상은 자동으로 업로드되거나 공유되지 않습니다.</p><button class="secondary-button" data-action="upload-video">첫 번째 영상 가져오기 ${icon('arrow')}</button></section>`}</div>`}<div class="privacy-strip">${icon('shield')}<div><h3>기기 내 영상 보관</h3><p>실제 사용자 영상만 저장됩니다. 영상과 메타데이터는 현재 브라우저의 IndexedDB에 보관하며, 브라우저 데이터 삭제 시 사라질 수 있습니다. 소중한 영상은 다운로드해 보관하세요.</p></div></div>`;}
function clipCard(clip){const url=URL.createObjectURL(clip.blob);clipUrls.push(url);const provenance=clip.provenance==='captured-browser-camera'?'카메라 촬영':'가져온 영상';return `<article class="panel clip-card"><button class="clip-preview" style="width:100%" data-action="play-clip" data-id="${esc(clip.id)}" aria-label="${esc(clip.name)} 재생"><video src="${url}#t=0.1" preload="metadata" muted playsinline></video><span class="clip-play-overlay"><span>${icon('play')}</span></span><span class="clip-source">${provenance}</span></button><div class="clip-card-body"><h3>${esc(clip.name)}</h3><p class="clip-meta">${new Date(clip.createdAt).toLocaleDateString('ko-KR')} &nbsp;·&nbsp; ${(clip.size/1024/1024).toFixed(1)} MB &nbsp;·&nbsp; ${esc(clip.metadata?.routeTitle||'내 영상')}</p><div class="clip-actions"><button class="subtle-button" data-action="download-clip" data-id="${esc(clip.id)}">${icon('download')} 영상</button><button class="subtle-button" data-action="export-clip" data-id="${esc(clip.id)}">JSON</button><button class="subtle-button" data-action="analyze-clip" data-id="${esc(clip.id)}">풍경 추정</button><button class="subtle-button" data-action="delete-clip" data-id="${esc(clip.id)}" aria-label="${esc(clip.name)} 삭제">${icon('trash')}</button></div><div id="analysis-${esc(clip.id)}"></div></div></article>`;}
function renderSettings(){if(state.moving)return intro('MAKE IT YOURS','설정','연결 상태와 개인정보 설정을 확인하세요.')+restricted('설정은 정차 후에');const provider=state.providerStatus;return `${intro('MAKE IT YOURS','설정','현재 작동하는 기능과 앞으로 연결할 기능을 투명하게 구분합니다.')}<div class="settings-grid"><section class="panel setting-panel"><h2>연결과 기능 상태</h2><p>이 화면은 독립 실행되는 웹 프로토타입입니다. 차량 하드웨어나 Pleos 차량 신호와 연결되어 있지 않습니다.</p>${[
['취향 기반 코스 추천','8개 큐레이션 코스 · 시간·거리·점수는 시연 값','작동 중',''],
['웹 사운드 데모','합성 앰비언트 · 사용자 음원 재생 지원 · Pleos 앱의 YouTube 추천과 별도','작동 중',''],
['브라우저 GPS','사용자 권한 허용 후 위치 수신 · 차량 GPS 아님','권한 필요','pending'],
['개인 영상 기록','IndexedDB 저장 · 카메라 녹화 · 직접 다운로드','작동 중',''],
['실시간 날씨','코스 출발지 Open-Meteo 공개 API · 온라인 필요','API 연결',''],
['도로 경로',provider.routing?.label||'서버 환경변수에 경로 API 키 설정 필요',provider.routing?.configured?'설정됨':'키 필요',provider.routing?.configured?'':'pending'],
['관광정보 API',provider.tourism?.label||'한국관광공사 API 키 설정 필요',provider.tourism?.configured?'설정됨':'키 필요',provider.tourism?.configured?'':'pending'],
['차량 신호 · 차량 카메라','Pleos 차량 API·권한·실차 테스트 필요','미연결','off'],
['경관 인식 모델','현재 경유지 기반 샘플 / 영상 색상 통계 추정','모델 미연결','off'],
['선택형 AI 코스 추천',provider.ai?.label||'OpenAI 서버 API 키 필요 · 사용자 실행 시에만 호출',provider.ai?.configured?'연결 준비':'키 필요',provider.ai?.configured?'':'pending'],
].map(([title,description,status,cls])=>`<div class="setting-row"><div><h3>${title}</h3><p>${esc(description)}</p></div><span class="status-tag ${cls}">${status}</span></div>`).join('')}</section><div class="main-column"><section class="panel setting-panel"><h2>드라이브 설정</h2><p>설정과 저장 코스는 현재 브라우저에만 보관합니다.</p><label class="setting-check"><input id="auto-sound-setting" type="checkbox" ${state.autoSound?'checked':''}> 경관이 바뀌면 오리지널 사운드 자동 전환</label><label class="setting-check"><input id="location-setting" type="checkbox" ${state.includeLocation?'checked':''}> 영상 메타데이터에 허용한 GPS 위치 포함</label><div class="setting-row"><div><h3>기록은 직접 내보내기</h3><p>자동 클라우드 업로드와 자동 공유는 없습니다.</p></div><span class="status-tag">기기 내 보관</span></div><button class="secondary-button" data-action="export-settings" style="margin-top:18px">${icon('download')} 내 설정 다운로드</button></section><section class="panel setting-panel"><div class="about-logo">SCENIC</div><h2>경관 기반 드라이브</h2><p style="margin-top:10px">보조 웹 데모에서 예시 코스, 합성 사운드,<br>기기 내 영상 기록을 확인할 수 있습니다.<br>Pleos 앱과 지원 기능이 다릅니다.</p><div class="tech-list"><span>취향 기반 큐레이션</span><span>경관 구간 사운드</span><span>개인 기기 영상 보관</span><span>운전 중 UI 제한</span></div><p class="provenance-note">${esc(dataNotice)} 운전 모드는 사용자가 직접 켜는 시연 상태이며 실제 차량 안전 상태를 감지하지 않습니다.</p><div class="setting-links">${fixtureSources.slice(0,4).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</div></section></div></div>`;}

function render(){
  if(map){map.remove();map=null;mapMarker=null;}
  clipUrls.forEach(URL.revokeObjectURL);clipUrls=[];
  updateHeader();
  const renderer={explore:renderExplore,journey:renderJourney,drive:renderDrive,memories:renderMemories,settings:renderSettings};
  main.innerHTML=renderer[state.view]();
  if($('#map-canvas'))initMap();
  if(state.cameraActive&&$('#camera-preview'))$('#camera-preview').srcObject=cameraStream;
}
function navigate(view){if(!['explore','journey','drive','memories','settings'].includes(view))return;if((state.cameraActive||state.cameraPending)&&view!=='memories'){toast('다른 화면으로 이동하기 전에 녹화를 종료해 주세요.');return;}state.view=view;if(location.hash!==`#${view}`){location.hash=view;}else{render();}if(view==='memories')refreshClips();}
function selectRoute(id,open=true,preserveAI=false){if(!allowed('browse'))return;const route=routes.find(r=>r.id===id);if(!route)return;if(!preserveAI)invalidateAI();stopTracking();state.selected=route;state.progress=0;state.scene=route.theme;state.roadRoute=null;state.roadLoading=false;state.places=[];state.placesLoaded=false;state.placesLoading=false;roadToken++;placesToken++;if(state.autoSound)audioEngine.setScene(state.scene);persist();updateWeather();if(open)navigate('journey');else render();}
function applyFilters(){if(!allowed('edit'))return;invalidateAI();const ranked=getRanked();if(ranked.length&&!ranked.some(r=>r.id===state.selected.id)){selectRoute(ranked[0].id,false);}else{persist();render();}}
function stopTracking(){gpsToken++;if(simTimer!==null){clearInterval(simTimer);simTimer=null;}state.simulation=false;if(state.gpsWatch!==null){navigator.geolocation?.clearWatch(state.gpsWatch);state.gpsWatch=null;}}
function setMoving(value){if(value&&(state.cameraActive||state.cameraPending)){toast('카메라 사용을 마친 뒤 운전 모드를 시작해 주세요.');return;}state.moving=value;if(value){invalidateAI();closeVideo();}else stopTracking();render();}
function startSimulation(){if(state.cameraActive||state.cameraPending){toast('카메라 녹화를 종료한 뒤 시작해 주세요.');return;}invalidateAI();stopTracking();if(state.progress>=1)state.progress=0;state.simulation=true;state.moving=true;state.gps=null;state.roadRoute=null;state.roadLoading=false;roadToken++;state.mapMode='diagram';state.gpsStatus='';closeVideo();state.view='drive';location.hash='drive';render();simTimer=setInterval(()=>{state.progress=Math.min(1,state.progress+1/120);const p=projectProgress(state.selected,state.progress);const changed=state.scene!==p.scene;state.scene=p.scene;if(state.autoSound)audioEngine.setScene(p.scene);if(state.progress>=1){stopTracking();state.moving=false;render();toast('시뮬레이션이 완료되었습니다.');return;}if(state.view==='drive'){if(changed)render();else updateDriveProgress(p);}},1000);toast('시뮬레이션이 시작됐어요. 실제 주행 안내가 아닙니다.');}
function updateDriveProgress(p){if($('#drive-remaining'))$('#drive-remaining').innerHTML=`${p.remainingMin}<small>분</small>`;if($('#drive-distance'))$('#drive-distance').innerHTML=`${p.distanceKm.toFixed(1)}<small> / ${state.selected.distanceKm} km</small>`;if($('#drive-progress-bar'))$('#drive-progress-bar').style.width=`${state.progress*100}%`;if($('#drive-progress-value'))$('#drive-progress-value').textContent=`${Math.round(state.progress*100)}% 진행`;if(mapMarker)mapMarker.setLatLng([p.lat,p.lon]);else if($('#map-canvas')&&state.mapMode==='diagram')renderDiagram();}
async function startGPS(){if(!allowed('edit'))return;if(!navigator.geolocation){toast('이 브라우저는 위치 정보를 지원하지 않습니다.',true);return;}if(!window.isSecureContext){toast('GPS 사용에는 HTTPS 또는 localhost 접속이 필요합니다.',true);return;}invalidateAI();stopTracking();state.gps=null;const token=++gpsToken;state.moving=true;state.mapMode='online';state.gpsStatus='위치 권한 요청 중…';render();state.gpsWatch=navigator.geolocation.watchPosition(position=>{if(token!==gpsToken)return;state.gps={lat:position.coords.latitude,lon:position.coords.longitude,accuracy:position.coords.accuracy,timestamp:position.timestamp};let near={distance:Infinity,fraction:0};for(let n=0;n<=100;n++){const p=projectProgress(state.selected,n/100),d=haversineKm([state.gps.lat,state.gps.lon],[p.lat,p.lon]);if(d<near.distance)near={distance:d,fraction:n/100};}if(near.distance>5){state.gpsStatus=`현재 위치가 예시 코스에서 ${near.distance.toFixed(1)} km 떨어져 있습니다. 진행률을 추정하지 않습니다.`;}else{state.progress=near.fraction;state.scene=projectProgress(state.selected,state.progress).scene;state.gpsStatus=`예시 코스 가까운 지점에 투영한 진행 추정 · 거리 오차 ${Math.round(near.distance*1000)}m`;if(state.autoSound)audioEngine.setScene(state.scene);}state.moving=true;closeVideo();render();},error=>{if(token!==gpsToken)return;stopTracking();state.moving=false;state.gpsStatus=error.code===1?'위치 권한이 거부되었습니다. 브라우저 설정에서 권한을 변경하거나 시뮬레이션을 이용하세요.':'위치를 가져오지 못했습니다. 실외에서 다시 시도하거나 시뮬레이션을 이용하세요.';render();toast(state.gpsStatus,true);},{enableHighAccuracy:true,maximumAge:5000,timeout:15000});}
function renderDiagram(){const el=$('#map-canvas');if(!el)return;const coordinates=state.roadRoute?.coordinates||state.selected.coordinates;const lats=coordinates.map(p=>p[0]),lons=coordinates.map(p=>p[1]);const minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons);const x=lon=>100+(lon-minLon)/(maxLon-minLon||.01)*530,y=lat=>310-(lat-minLat)/(maxLat-minLat||.01)*190;const path=coordinates.map((p,i)=>`${i?'L':'M'}${x(p[1]).toFixed(1)},${y(p[0]).toFixed(1)}`).join(' ');const p=state.gpsWatch!==null&&state.gps?state.gps:projectProgress(state.selected,state.progress);el.innerHTML=`<svg viewBox="0 0 800 430" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%" role="img" aria-label="경관 포인트의 지리 좌표를 연결한 도식. 실제 도로가 아닙니다."><defs><pattern id="map-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d8e0e8" stroke-width=".6"/></pattern></defs><rect width="800" height="430" fill="#e8eef5"/><rect width="800" height="430" fill="url(#map-grid)"/><text x="28" y="86" fill="#526171" font-size="11" font-family="Asta Sans, sans-serif" letter-spacing="2">SCENIC ROUTE DIAGRAM</text><text x="28" y="105" fill="#526171" font-size="11" font-family="Asta Sans, sans-serif">지리 좌표 기반 도식 · 실제 도로 아님</text><path d="${path}" fill="none" stroke="#002c5f" stroke-width="3" stroke-linejoin="round" stroke-dasharray="6 5"/>${state.selected.stops.map((s,i)=>`<g><circle cx="${x(s.lon)}" cy="${y(s.lat)}" r="10" fill="#002c5f" stroke="#ffffff" stroke-width="3"/><text x="${x(s.lon)}" y="${y(s.lat)+3}" fill="#ffffff" font-size="9" text-anchor="middle">${i+1}</text><rect x="${Math.max(10,Math.min(620,x(s.lon)+17))}" y="${y(s.lat)-14}" width="152" height="28" rx="3" fill="#ffffff"/><text x="${Math.max(18,Math.min(628,x(s.lon)+25))}" y="${y(s.lat)+4}" fill="#002c5f" font-size="11" font-family="Asta Sans, sans-serif">${esc(s.name)}</text></g>`).join('')}${state.view==='drive'?`<circle cx="${x(p.lon)}" cy="${y(p.lat)}" r="13" fill="#ffffff"/><circle cx="${x(p.lon)}" cy="${y(p.lat)}" r="7" fill="#002c5f" stroke="#ffffff" stroke-width="2"/>`:''}<g transform="translate(753 83)"><path d="m0-12 5 20-5-4-5 4Z" fill="#002c5f"/><text y="-20" text-anchor="middle" font-size="10" fill="#526171">N</text></g></svg>`;}

function initMap(){if(state.mapMode==='diagram'){renderDiagram();return;}if(!globalThis.L){state.mapMode='diagram';render();toast('온라인 지도를 불러올 수 없어 코스 도식으로 표시합니다.');return;}const coordinates=state.roadRoute?.coordinates||state.selected.coordinates;try{map=L.map('map-canvas',{zoomControl:false,scrollWheelZoom:false}).setView(coordinates[0],12);const activeMap=map;L.control.zoom({position:'bottomright'}).addTo(map);let failures=0;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>',maxZoom:18}).on('tileerror',()=>{if(map!==activeMap)return;if(++failures===5){state.mapMode='diagram';render();toast('지도 네트워크 연결이 불안정해 코스 도식을 표시합니다.');}}).addTo(map);const polyline=L.polyline(coordinates,{color:'#002c5f',weight:4,dashArray:state.roadRoute?null:'8 6'}).addTo(map);map.fitBounds(polyline.getBounds(),{padding:[55,65]});state.selected.stops.forEach((s,i)=>{L.circleMarker([s.lat,s.lon],{radius:7,fillColor:'#002c5f',fillOpacity:1,color:'#ffffff',weight:3}).addTo(map).bindPopup(`${i+1}. ${esc(s.name)}<br>${esc(themeNames[s.scene])} 경관 포인트`);});if(state.view==='drive'){const p=state.gpsWatch!==null&&state.gps?state.gps:projectProgress(state.selected,state.progress);if(state.gpsWatch!==null&&state.gps)map.setView([p.lat,p.lon],13);mapMarker=L.circleMarker([p.lat,p.lon],{radius:9,fillColor:'#002c5f',fillOpacity:1,color:'#ffffff',weight:4}).addTo(map);}setTimeout(()=>map?.invalidateSize(),60);}catch{state.mapMode='diagram';render();}}

async function refreshClips(){state.clipsLoading=true;state.clipsError='';if(state.view==='memories')render();try{state.clips=await listClips();}catch(error){state.clipsError=error.message||'기록을 불러올 수 없습니다.';}finally{state.clipsLoading=false;if(state.view==='memories')render();}}
function metadata(provenance){const p=projectProgress(state.selected,state.progress);return {app:'SCENIC',version:'0.1',provenance,recordedAt:new Date().toISOString(),routeId:state.selected.id,routeTitle:state.selected.title,routeSource:'curated-demo',routeProgress:state.progress,scene:p.scene,sceneSource:'curated-route-anchor',gps:state.includeLocation&&state.gps?{...state.gps,source:'browser-geolocation'}:null,privacy:'local-browser-only',vehicleConnected:false};}
async function storeVideo(blob,name,provenance,extra={}){try{if(!blob.type.startsWith('video/'))throw new Error('지원되는 영상 파일을 선택해 주세요.');if(blob.size>MAX_BYTES)throw new Error('100 MB 이하의 영상만 저장할 수 있습니다.');if(blob.size===0)throw new Error('영상에 데이터가 없습니다.');await saveClip({name,blob,mimeType:blob.type,provenance,metadata:{...metadata(provenance),...extra}});toast('이 기기에 기록을 저장했어요.');await refreshClips();}catch(error){toast(`저장하지 못했습니다. ${error.message}`,true);}}
async function startCamera(){if(!allowed('video')||state.cameraActive||state.cameraPending)return;if(!window.isSecureContext){toast('카메라 사용에는 HTTPS 또는 localhost 접속이 필요합니다.',true);return;}state.cameraPending=true;render();try{await camera.start({onPreview(stream){state.cameraPending=false;state.cameraActive=true;cameraStream=stream;recordingStarted=Date.now();render();},async onStopped(result){state.cameraActive=false;state.cameraPending=false;cameraStream=null;render();if(result?.error){toast(result.error.message||'녹화를 저장할 수 없습니다.',true);return;}if(result?.blob){const stamp=new Date().toLocaleString('ko-KR');await storeVideo(result.blob,`나의 드라이브 · ${stamp}`,'captured-browser-camera',{durationMs:result.durationMs||Date.now()-recordingStarted,audioRecorded:false});}}});}catch(error){state.cameraActive=false;state.cameraPending=false;cameraStream=null;render();toast(error.name==='NotAllowedError'?'카메라 권한이 거부되었습니다. 영상 파일 가져오기를 이용할 수 있어요.':error.message||'카메라를 시작하지 못했습니다.',true);}}
function closeVideo(){const video=$('#clip-player');video.pause();video.removeAttribute('src');video.load();if($('#video-dialog').open)$('#video-dialog').close();if(dialogUrl){URL.revokeObjectURL(dialogUrl);dialogUrl=null;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportClipData(clip){return {id:clip.id,name:clip.name,createdAt:clip.createdAt,mimeType:clip.mimeType,size:clip.size,provenance:clip.provenance,metadata:clip.metadata};}
function exportJSON(data,name){download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),name);}
async function analyzeClip(clip){if(!allowed('video'))return;const out=document.getElementById(`analysis-${clip.id}`);if(out)out.innerHTML='<p class="analysis-result">영상의 첫 프레임 색상을 살펴보고 있어요…</p>';const video=document.createElement('video'),url=URL.createObjectURL(clip.blob);video.muted=true;video.preload='auto';video.src=url;try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('이 영상 형식은 프레임 분석을 지원하지 않습니다.')),8000);video.onloadeddata=()=>{clearTimeout(timer);resolve();};video.onerror=()=>{clearTimeout(timer);reject(new Error('영상 프레임을 읽을 수 없습니다.'));};video.load();});const canvas=document.createElement('canvas');canvas.width=80;canvas.height=45;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(video,0,0,80,45);const pixels=context.getImageData(0,0,80,45).data;let green=0,blue=0,neutral=0;for(let i=0;i<pixels.length;i+=4){const [r,g,b]=[pixels[i],pixels[i+1],pixels[i+2]];if(g>r*1.08&&g>b*1.03)green++;if(b>r*1.12&&b>g*.95)blue++;if(Math.max(r,g,b)-Math.min(r,g,b)<35)neutral++;}const scene=green>blue&&green>450?'forest':blue>450?'coast':neutral>1700?'city':'lake';const message=`색상 통계로 ${themeNames[scene]} 분위기를 추정했어요. 학습된 AI 모델이나 실제 장소 인식이 아니며 정확도를 보장하지 않습니다.`;if(out)out.innerHTML=`<p class="analysis-result">${esc(message)}<br><button class="text-button" data-action="scene" data-value="${scene}">${selectSound(scene).title} 사운드 선택 ${icon('arrow')}</button></p>`;}catch(error){if(out)out.innerHTML=`<p class="inline-error">${esc(error.message)}</p>`;}finally{video.removeAttribute('src');video.load();URL.revokeObjectURL(url);}}

document.addEventListener('click',async(event)=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const {action,value,id}=button.dataset;
  try{
    if(action==='view')navigate(value);
    else if(action==='theme'){if(!allowed('edit'))return;state.filters.theme=value;applyFilters();}
    else if(action==='bookmark'){if(!allowed('edit'))return;const saved=state.bookmarks.includes(id);state.bookmarks=saved?state.bookmarks.filter(v=>v!==id):[...state.bookmarks,id];persist();applyFilters();toast(saved?'저장한 코스에서 해제했어요.':'나의 코스에 저장했어요.');}
    else if(action==='select-route')selectRoute(id);
    else if(action==='all-routes'){if(!allowed('browse'))return;state.allResults=!state.allResults;state.filters.query='';invalidateAI();render();}
    else if(action==='reset-filters'){state.filters={region:'all',theme:'all',maxMinutes:180,query:''};state.sort='match';applyFilters();}
    else if(action==='recommend'){if(!allowed('edit'))return;const r=getRanked();if(r.length){selectRoute(r[0].id,false);toast(`${r.length}개 코스에서 지금 취향에 어울리는 길을 골랐어요.`);}else{render();toast('조건에 맞는 코스가 없어요. 시간 예산을 늘려보세요.');}}
    else if(action==='ai-recommend'){if(!allowed('edit')||state.aiLoading)return;const candidates=getRanked(),candidateIds=candidates.map(r=>r.id);if(!candidateIds.length){toast('먼저 조건에 맞는 코스를 찾아주세요.');return;}const preferences={...state.filters},signature=JSON.stringify({preferences,candidateIds}),token=++aiToken;state.aiLoading=true;state.aiResult=null;state.aiError='';render();try{const result=await recommendWithAI(candidateIds,preferences);if(token!==aiToken||state.moving||JSON.stringify({preferences:{...state.filters},candidateIds:getRanked().map(r=>r.id)})!==signature)return;const recommendations=Array.isArray(result.recommendations)?result.recommendations.filter(item=>candidateIds.includes(item.routeId)&&typeof item.reason==='string'):[];if(!recommendations.length)throw new Error('현재 후보 코스에 맞는 AI 응답을 받지 못했습니다. 기본 취향 추천을 이용해 주세요.');state.aiResult={source:result.source||'OpenAI',model:result.model||'API 응답 모델',generatedAt:result.generatedAt,recommendations};state.aiLoading=false;selectRoute(recommendations[0].routeId,false,true);toast('OpenAI의 실제 추천을 받았어요. 추천 이유를 확인해 보세요.');}catch(error){if(token===aiToken){state.aiError=error.message||'AI 추천을 가져오지 못했습니다. 기본 취향 추천을 이용해 주세요.';toast(state.aiError,true);}}finally{if(token===aiToken){state.aiLoading=false;render();}}}
    else if(action==='ai-cancel'){invalidateAI();render();toast('이번 AI 추천 결과의 적용을 취소했어요.');}
    else if(action==='sound-play'){if(audioEngine.getState().playing)audioEngine.pause();else if(audioEngine.getState().source==='file')await audioEngine.play();else await audioEngine.start(state.scene);render();}
    else if(action==='sound-next'||action==='sound-prev'){const scenes=['lake','coast','forest','city'],at=scenes.indexOf(state.scene);state.scene=scenes[(at+(action==='sound-next'?1:3))%4];await audioEngine.start(state.scene);render();}
    else if(action==='scene'){if(!allowed('edit'))return;state.scene=value;await audioEngine.start(value);render();toast(`${themeNames[value]} 풍경 사운드를 재생합니다.`);}
    else if(action==='upload-audio'){if(allowed('edit'))$('#audio-file-input').click();}
    else if(action==='original-audio'){if(!allowed('edit'))return;await audioEngine.start(state.scene);render();}
    else if(action==='toggle-map'){state.mapMode=state.mapMode==='diagram'?'online':'diagram';render();}
    else if(action==='start-simulation')startSimulation();
    else if(action==='start-gps')startGPS();
    else if(action==='park'){setMoving(false);toast('정차 모드로 전환했어요.');}
    else if(action==='finish-drive'){stopTracking();state.moving=false;state.progress=0;state.scene=state.selected.theme;render();toast('시뮬레이션을 종료했어요.');}
    else if(action==='road-route'){if(!allowed('edit'))return;const selected=state.selected,token=++roadToken;state.roadLoading=true;render();try{const result=await getRoadRoute(selected);if(token!==roadToken||state.selected.id!==selected.id)return;state.roadRoute=result;state.mapMode='online';toast('도로 경로 API에서 경로를 가져왔어요.');}catch(error){if(token===roadToken)toast(error.message,true);}finally{if(token===roadToken){state.roadLoading=false;render();}}}
    else if(action==='load-places'){if(!allowed('browse'))return;const selected=state.selected,token=++placesToken;state.placesLoading=true;render();try{const [lat,lon]=selected.coordinates[0];const result=await searchPlaces({lat,lon,radiusMeters:10000});if(token!==placesToken||state.selected.id!==selected.id)return;state.places=Array.isArray(result)?result:[];state.placesLoaded=true;toast(`${state.places.length}개의 주변 관광정보를 확인했어요.`);}catch(error){if(token===placesToken)toast(error.message,true);}finally{if(token===placesToken){state.placesLoading=false;render();}}}
    else if(action==='upload-video'){if(allowed('video'))$('#video-file-input').click();}
    else if(action==='camera-start')startCamera();
    else if(action==='camera-stop'){if(allowed('video'))await camera.stop();}
    else if(action==='reload-clips')refreshClips();
    else if(action==='play-clip'){if(!allowed('video'))return;const clip=state.clips.find(c=>c.id===id);if(!clip)return;closeVideo();dialogUrl=URL.createObjectURL(clip.blob);$('#video-dialog-title').textContent=clip.name;$('#clip-player').src=dialogUrl;$('#video-dialog').showModal();try{await $('#clip-player').play();}catch{toast('재생 버튼을 누르거나 지원되는 형식의 영상을 사용해 주세요.');}}
    else if(action==='delete-clip'){if(!allowed('edit'))return;const clip=state.clips.find(c=>c.id===id);if(!clip)return;if(!confirm(`“${clip.name}” 기록을 이 기기에서 삭제할까요? 이 작업은 되돌릴 수 없습니다.`))return;await deleteClip(id);await refreshClips();toast('기록을 삭제했어요.');}
    else if(action==='download-clip'){if(!allowed('edit'))return;const clip=state.clips.find(c=>c.id===id);if(clip)download(clip.blob,clip.name.match(/\.(mp4|webm|mov|m4v)$/i)?clip.name:`${clip.name}.${clip.mimeType.includes('mp4')?'mp4':'webm'}`);}
    else if(action==='export-clip'){if(!allowed('edit'))return;const clip=state.clips.find(c=>c.id===id);if(clip)exportJSON(exportClipData(clip),`scenic-record-${clip.id}.json`);}
    else if(action==='export-all'){if(!allowed('edit'))return;exportJSON({app:'SCENIC',exportedAt:new Date().toISOString(),records:state.clips.map(exportClipData),notice:'실제 사용자 파일 기록. 코스와 경관 메타데이터는 별도 표시된 시연용 데이터입니다.'},'scenic-my-moments.json');}
    else if(action==='export-settings'){if(!allowed('edit'))return;exportJSON({app:'SCENIC',preferences:loadPreferences(),exportedAt:new Date().toISOString()},'scenic-preferences.json');}
    else if(action==='analyze-clip'){const clip=state.clips.find(c=>c.id===id);if(clip)await analyzeClip(clip);}
  }catch(error){toast(error.message||'작업을 완료하지 못했습니다. 다시 시도해 주세요.',true);}
});
document.addEventListener('change',async(event)=>{
  const target=event.target;
  if(target.id==='region-filter'){state.filters.region=target.value;applyFilters();}
  else if(target.id==='time-filter'){if(!allowed('edit'))return;const minutes=Number(target.value);if(!Number.isInteger(minutes)||minutes<1||minutes>720){target.value=String(state.filters.maxMinutes);toast('여유 시간은 1분부터 720분까지 정수로 입력해 주세요.',true);return;}state.filters.maxMinutes=minutes;applyFilters();}
  else if(target.id==='sort-select'){if(!allowed('edit'))return;state.sort=target.value;applyFilters();}
  else if(target.id==='auto-sound-setting'){state.autoSound=target.checked;persist();toast('사운드 전환 설정을 저장했어요.');}
  else if(target.id==='location-setting'){state.includeLocation=target.checked;persist();toast(target.checked?'허용한 브라우저 GPS만 기록에 포함합니다.':'새 기록에 GPS 위치를 포함하지 않습니다.');}
  else if(target.id==='audio-file-input'){const file=target.files?.[0];target.value='';if(!file||!allowed('edit'))return;try{await audioEngine.loadFile(file);await audioEngine.play();render();toast('나의 음악을 재생합니다.');}catch(error){toast(error.message,true);}}
  else if(target.id==='video-file-input'){const file=target.files?.[0];target.value='';if(!file||!allowed('video'))return;await storeVideo(file,file.name,'user-upload');}
  else if(target.id==='volume-control'){persist();}
});
document.addEventListener('input',event=>{const target=event.target;if(target.id==='volume-control'){state.volume=Number(target.value)/100;audioEngine.setVolume(state.volume);}else if(target.id==='drive-scrubber'&&!state.moving){state.progress=Number(target.value)/100;const p=projectProgress(state.selected,state.progress);state.scene=p.scene;if(state.autoSound)audioEngine.setScene(p.scene);updateDriveProgress(p);}else if(target.id==='route-search'){state.filters.query=target.value;invalidateAI();if($('#ai-panel-slot'))$('#ai-panel-slot').innerHTML=aiPanel();}});
document.addEventListener('change',event=>{if(event.target.id==='drive-scrubber')render();});
document.addEventListener('submit',event=>{if(event.target.id==='recommendation-form'){event.preventDefault();if(!allowed('edit'))return;const ranked=getRanked();if(ranked.length)selectRoute(ranked[0].id,false);else render();toast(ranked.length?`${ranked.length}개의 풍경 코스를 찾았어요.`:'검색 조건에 맞는 코스가 없어요.');}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if((state.cameraActive||state.cameraPending)&&next!=='memories'){location.hash='memories';toast('녹화를 종료한 뒤 이동해 주세요.');return;}state.view=['explore','journey','drive','memories','settings'].includes(next)?next:'explore';render();window.scrollTo({top:0,behavior:'instant'});if(state.view==='memories')refreshClips();});
$('#drive-mode-toggle').addEventListener('click',()=>{if(state.cameraActive||state.cameraPending){toast('카메라 사용을 마친 뒤 운전 모드를 시작해 주세요.');return;}if(state.moving){setMoving(false);toast('정차 모드로 전환했어요.');}else{state.view='drive';location.hash='drive';setMoving(true);toast('운전 모드 UI 시연입니다. 실제 차량과 연결되지 않습니다.');}});
$('#close-video').addEventListener('click',closeVideo);
$('#video-dialog').addEventListener('cancel',()=>closeVideo());
$('#video-dialog').addEventListener('click',event=>{if(event.target===$('#video-dialog'))closeVideo();});
window.addEventListener('beforeunload',event=>{if(state.cameraActive){event.preventDefault();event.returnValue='';}});
window.addEventListener('pagehide',()=>{invalidateAI();roadToken++;placesToken++;state.roadLoading=false;state.placesLoading=false;stopTracking();camera.cleanup();state.cameraActive=false;state.cameraPending=false;cameraStream=null;audioEngine.cleanup();closeVideo();clipUrls.forEach(URL.revokeObjectURL);});
window.addEventListener('pageshow',event=>{if(event.persisted){state.moving=false;render();if(state.view==='memories')refreshClips();}});
window.addEventListener('offline',()=>toast('오프라인이에요. 저장된 코스와 개인 기록은 계속 이용할 수 있습니다.'));
$('#location-icon').innerHTML=icon('pin');
updateClock();setInterval(updateClock,30000);
render();updateWeather();getProviderStatus().then(status=>{state.providerStatus=status;if(state.view==='settings')render();}).catch(()=>{});if(state.view==='memories')refreshClips();
if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
